// Run Once for All Items — one client's campaigns (Aimfox GET /campaigns is not paginated).
const pages = $input.all();
const client = $('Split in Batches').first().json;

const allCampaigns = [];
for (const page of pages) {
  const items = page.json?.campaigns;          // Aimfox returns { status, campaigns:[...] }
  if (Array.isArray(items)) allCampaigns.push(...items);
}

if (allCampaigns.length === 0) {
  return [{ json: { sql: 'SELECT 1', count: 0, client_name: client.name } }];
}

// Aimfox campaign states observed: ACTIVE, DONE. Unknown → 'draft' (self-heals: status is in the
// UPDATE clause, so a later run with a recognised state corrects it). PAUSED/STOPPED added defensively.
const statusMap = {
  'ACTIVE':    'active',
  'DONE':      'completed',
  'PAUSED':    'stopped',
  'STOPPED':   'stopped',
  'DRAFT':     'draft',
};

const safe = s => String(s ?? '').replace(/'/g, "''");
const AIMFOX_SEQ = '00000000-0000-4000-a000-000000000003';

const values = allCampaigns.map(c => {
  const status = statusMap[c.state] || 'draft';
  const name   = safe(c.name);
  const extId  = safe(c.id);                    // Aimfox campaign UUID
  const dbSize = Number(c.target_count) || 0;   // audience target
  let startDate = 'NULL';
  if (typeof c.created_at === 'number' && isFinite(c.created_at)) {
    startDate = "'" + new Date(c.created_at).toISOString().substring(0, 10) + "'";
  }
  // type + sequencer_id are set here (INSERT) and NOT in the UPDATE clause below, so an Aimfox
  // campaign can never be silently retyped to emailbison/email by a later run.
  return `('${safe(client.id)}', '${extId}', '${AIMFOX_SEQ}'::uuid, 'outreach'::campaign_type, '${name}', '${status}'::campaign_status, ${dbSize}, ${startDate})`;
}).join(',\n');

const sql = `
INSERT INTO public.campaigns
  (client_id, external_id, sequencer_id, type, name, status, database_size, start_date)
VALUES
${values}
ON CONFLICT (external_id) DO UPDATE SET
  name          = EXCLUDED.name,
  status        = EXCLUDED.status,
  database_size = EXCLUDED.database_size,
  updated_at    = NOW()
RETURNING external_id, name, status
`;

return [{ json: { sql, count: allCampaigns.length, client_name: client.name } }];
